"""Leçons originales : programme scolaire inspiré de la LOMLOE + progression CECRL inspirée du PCIC.
Ces contenus ne constituent ni un manuel officiel espagnol ni une certification CECRL.
"""
from __future__ import annotations

def L(titre, notion, exemples, texte, question, choix, reponse, mission):
    assert reponse in choix and len(choix)==3,(titre,reponse,choix)
    return dict(titre=titre,notion=notion,exemples=exemples,texte=texte,
                question=question,choix=choix,reponse=reponse,mission=mission)

